"""Repository-aware launcher for the ScholarFlow Python domain bridge."""

from __future__ import annotations

import sys
from pathlib import Path

# Pi exchanges JSON with this process.  Never let the Windows console code page
# corrupt or reject Unicode generated by the model (for example symbols in an
# artifact body).
if hasattr(sys.stdout, "reconfigure"):
    sys.stdout.reconfigure(encoding="utf-8")
if hasattr(sys.stderr, "reconfigure"):
    sys.stderr.reconfigure(encoding="utf-8")

REPOSITORY_ROOT = Path(__file__).resolve().parents[3]
if str(REPOSITORY_ROOT) not in sys.path:
    sys.path.insert(0, str(REPOSITORY_ROOT))

from scholarflow.pi_bridge import main  # noqa: E402


if __name__ == "__main__":
    raise SystemExit(main())
